/// <summary>
/// Class is used to make copy of <c>UPSPriceTermJournalTrans</c> records. Should be called from form UPSPriceTermJournalTrans.
/// </summary>
final class UPSPriceTermJournalTransCopy
{
    FormDataSource upsPriceTermJournalTrans_ds;

    #OCCRetryCount

}

Method.Source:
private void run()
{
    UPSPriceTermJournalTrans    upsPriceTermJournalTransNew;
    MultiSelectionHelper        selectionHelper = MultiSelectionHelper::construct();

    selectionHelper.parmDataSource(upsPriceTermJournalTrans_ds);

    try
    {
        ttsbegin;

        UPSPriceTermJournalTrans upsPriceTermJournalTransOrig = selectionHelper.getFirst();
        while (upsPriceTermJournalTransOrig)
        {
            upsPriceTermJournalTransNew.clear();
            upsPriceTermJournalTransNew.initfromUPSPriceTermJournalTrans(upsPriceTermJournalTransOrig);
            upsPriceTermJournalTransNew.PricingRule = UPSPricingRule::find(upsPriceTermJournalTransOrig.PricingRule).copy().RecId;
            upsPriceTermJournalTransNew.insert();

            upsPriceTermJournalTransOrig = selectionHelper.getNext();
        }

        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::Error)
    {
        ttsabort;
        Box::stop("@GLS110288");
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

private FormDataSource formDataSource(FormDataSource _upsPriceTermJournalTrans_ds = upsPriceTermJournalTrans_ds)
{
    upsPriceTermJournalTrans_ds = _upsPriceTermJournalTrans_ds;

    return upsPriceTermJournalTrans_ds;
}

public static void main(Args _args)
{
    UPSPriceTermJournalTransCopy upsPriceTermJournalTransCopy = new UPSPriceTermJournalTransCopy();

    if (_args && _args.record() && _args.record().TableId == tableNum(UPSPriceTermJournalTrans))
    {
        Object upsPriceTermJournalTrans_ds = FormDataUtil::getFormDataSource(_args.record());

        upsPriceTermJournalTransCopy.formDataSource(upsPriceTermJournalTrans_ds);
        upsPriceTermJournalTransCopy.run();

        if (upsPriceTermJournalTrans_ds)
        {
            upsPriceTermJournalTrans_ds.executeQuery();
        }
    }
    else
        throw error(strFmt("@SYS27147", new DictClass(classIdGet(UPSPriceTermJournalTransCopy)).name()));
}
